/* 3. 设置你自己的中心加载图片，并强制绑定呼吸动画 */
#load-spinner {
    --spinner-size: 100px; /* 控制图片大小 */

    width: var(--spinner-size) !important;
    height: var(--spinner-size) !important;

    position: absolute !important;
    top: calc(58% - (var(--spinner-size) / 2)) !important;
    left: calc(50% - (var(--spinner-size) / 2)) !important;

    background-image: url('https://iili.io/CTM4MHg.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 🌟 核心：强制覆盖系统的旋转，绑定下面定义的 myBreathPulse 动画 */
    animation: myBreathPulse 1.5s infinite ease-in-out !important; 
    transition: none !important; 
}

/* 4. 👇 补上动画“剧本”：控制怎么变大变小（呼吸感） */
@keyframes myBreathPulse {
    0% { 
        opacity: 0.5; 
        transform: scale(0.85); /* 初始：变小、变暗 */
    }
    50% { 
        opacity: 1; 
        transform: scale(1.15); /* 中间：变大、全亮 */
    }
    100% { 
        opacity: 0.5; 
        transform: scale(0.85); /* 结束：恢复变小、变暗 */
    }
}
